import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.security.authentication.password.CompromisedPasswordChecker;
import org.springframework.security.authentication.password.CompromisedPasswordDecision;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest
@AutoConfigureMockMvc
class TempVerifyTest {

    @Autowired
    MockMvc mockMvc;

    @MockBean
    CompromisedPasswordChecker checker;

    @Test
    void whenNotCompromised_then200() throws Exception {
        when(checker.check("safePass")).thenReturn(new CompromisedPasswordDecision(false));
        mockMvc.perform(post("/users").contentType(MediaType.APPLICATION_JSON)
            .content("{\"emailId\":\"a@b.com\",\"password\":\"safePass\"}"))
            .andExpect(status().isOk());
    }

    @Test
    void whenCompromised_then400WithProblemDetail() throws Exception {
        when(checker.check("password")).thenReturn(new CompromisedPasswordDecision(true));
        mockMvc.perform(post("/users").contentType(MediaType.APPLICATION_JSON)
            .content("{\"emailId\":\"a@b.com\",\"password\":\"password\"}"))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.status").value(400))
            .andExpect(jsonPath("$.detail").value("The provided password is compromised and cannot be used"));
    }
}
